import { Icon } from "@/registry/erbium/ui/icon";

import { Field, FieldLabel } from "@/registry/erbium/ui/field";
import {
  InputGroup,
  InputGroupAddon,
  InputGroupInput,
  InputGroupText,
} from "@/registry/erbium/ui/input-group";

export default function InputInputGroupExample() {
  return (
    <Field>
      <FieldLabel>Website URL</FieldLabel>
      <InputGroup>
        <InputGroupInput placeholder="example.com" />
        <InputGroupAddon>
          <InputGroupText>https://</InputGroupText>
        </InputGroupAddon>
        <InputGroupAddon align="inline-end">
          <Icon name="info" />
        </InputGroupAddon>
      </InputGroup>
    </Field>
  );
}

import InputInputGroupExample from "../examples/input-input-group";

const Example = () => <InputInputGroupExample />;

export default Example;
